import 'package:supabase_flutter/supabase_flutter.dart';import '../config/supabase_config.dart';import '../models/models.dart';class ReferralRepository {  ReferralData _data = const ReferralData(code: 'WEEKEND-MX07');  SupabaseClient? get _client => SupabaseConfig.client;  ReferralData get referralData => _data;  Future<ReferralData> fetchReferralData(String userId) async {    final client = _client;    if (client == null) return _data;    try {      final referral = await client          .from('referrals')          .select()          .eq('referrer_id', userId)          .maybeSingle();      if (referral != null) {        final count = await client            .from('referrals')            .select()            .eq('referrer_id', userId);        _data = ReferralData(          code: referral['referral_code'] ?? 'WEEKEND-MX07',          invitedCount: (count as List).length,          verifiedCount: (count).where((r) => r['status'] == 'successful').length,        );      }    } catch (e) {      
// ignore
    }    return _data;  }  Future<void> createReferral(String referrerId, String refereeId, String code) async {    final client = _client;    if (client == null) return;    await client.from('referrals').insert({      'referrer_id': referrerId,      'referee_id': refereeId,      'referral_code': code,      'status': 'pending',    });  }}